import type {
  TimePeriodEnd,
  YearMonth,
} from 'utils/timePeriod/timePeriodAvailability';
import {
  HALF_MONTH_RANGES,
  HalfKey,
  isHalfKey,
  isQuarterKey,
  isYearMonth,
  QUARTER_MONTH_RANGES,
  QuarterKey,
  TimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

export function getMonthIndexFromEnd(end: YearMonth | null): number {
  if (!end) return 0;
  const parts = end.split('-');
  if (parts.length !== 2) return 0;
  return Number.parseInt(parts[1], 10) - 1;
}

export function getQuarterIndexFromEnd(end: QuarterKey | null): number {
  const map: Record<QuarterKey, number> = {
    [QuarterKey.Q1]: 0,
    [QuarterKey.Q2]: 1,
    [QuarterKey.Q3]: 2,
    [QuarterKey.Q4]: 3,
  };
  return (end ? map[end] : undefined) ?? 0;
}

export function getHalfIndexFromEnd(end: HalfKey | null): number {
  return end === HalfKey.H2 ? 1 : 0;
}

export interface SliderPositions {
  availableWidth: number;
  progressLeft: number;
  progressWidth: number;
  handleLeft: number;
  startDotLeft: number | null;
  showProgress: boolean;
}

/**
 * Computes the slider positions for the Time Period Selector.
 * @param type - Time period type.
 * @param end - End date of the period.
 * @param closedMonthIndex - Index of the closed month.
 * @returns The slider positions.
 */
export function computeSliderPositions(
  type: TimePeriodType,
  end: TimePeriodEnd,
  closedMonthIndex: number,
): SliderPositions {
  const availableWidth = ((closedMonthIndex + 0.5) / 12) * 100;

  switch (type) {
    case TimePeriodType.YTD: {
      const m = getMonthIndexFromEnd(isYearMonth(end) ? end : null);
      const pct = ((m + 0.5) / 12) * 100;
      return {
        availableWidth,
        progressLeft: 0,
        progressWidth: pct,
        handleLeft: pct,
        startDotLeft: null,
        showProgress: true,
      };
    }
    case TimePeriodType.R3M: {
      const m = getMonthIndexFromEnd(isYearMonth(end) ? end : null);
      const handlePct = ((m + 0.5) / 12) * 100;
      if (m < 2) {
        return {
          availableWidth,
          progressLeft: 0,
          progressWidth: handlePct,
          handleLeft: handlePct,
          startDotLeft: null,
          showProgress: true,
        };
      }
      const startPct = ((m - 2 + 0.5) / 12) * 100;
      return {
        availableWidth,
        progressLeft: startPct,
        progressWidth: (2 / 12) * 100,
        handleLeft: handlePct,
        startDotLeft: startPct,
        showProgress: true,
      };
    }
    case TimePeriodType.MTH: {
      const m = getMonthIndexFromEnd(isYearMonth(end) ? end : null);
      const pct = ((m + 0.5) / 12) * 100;
      return {
        availableWidth,
        progressLeft: 0,
        progressWidth: 0,
        handleLeft: pct,
        startDotLeft: null,
        showProgress: false,
      };
    }
    case TimePeriodType.QTR: {
      const q = getQuarterIndexFromEnd(isQuarterKey(end) ? end : null);
      const quarter = Object.values(QuarterKey)[q];
      const { startMonthIndex: startMonth, endMonthIndex: endMonth } =
        QUARTER_MONTH_RANGES[quarter];
      const startPct = ((startMonth + 0.5) / 12) * 100;
      const endPct = ((endMonth + 0.5) / 12) * 100;
      return {
        availableWidth,
        progressLeft: startPct,
        progressWidth: ((endMonth - startMonth) / 12) * 100,
        handleLeft: endPct,
        startDotLeft: startPct,
        showProgress: true,
      };
    }
    case TimePeriodType.HALF: {
      const h = getHalfIndexFromEnd(isHalfKey(end) ? end : null);
      const half = Object.values(HalfKey)[h];
      const { startMonthIndex: startMonth, endMonthIndex: endMonth } =
        HALF_MONTH_RANGES[half];
      const startPct = ((startMonth + 0.5) / 12) * 100;
      const endPct = ((endMonth + 0.5) / 12) * 100;
      return {
        availableWidth,
        progressLeft: startPct,
        progressWidth: ((endMonth - startMonth) / 12) * 100,
        handleLeft: endPct,
        startDotLeft: startPct,
        showProgress: true,
      };
    }
    case TimePeriodType.FY:
      return {
        availableWidth,
        progressLeft: 0,
        progressWidth: 100,
        handleLeft: 100,
        startDotLeft: null,
        showProgress: true,
      };
    default:
      return {
        availableWidth,
        progressLeft: 0,
        progressWidth: 98,
        handleLeft: 98,
        startDotLeft: null,
        showProgress: true,
      };
  }
}
